import { test, expect } from '@playwright/test';
test.describe('Accordion Interaction', () => {
  test('expand and collapse accordion sections', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.locator('button.accordion-button').filter({ hasText: 'What is Lorem Ipsum?' }).click();
    await expect(page.locator('button.accordion-button').filter({ hasText: 'What is Lorem Ipsum?' })).toHaveClass(/collapsed/, { timeout: 5000 });
    await page.locator('button.accordion-button').filter({ hasText: 'Where does it come from?' }).click();
    await expect(page.locator('button.accordion-button').filter({ hasText: 'Where does it come from?' })).not.toHaveClass(/collapsed/, { timeout: 5000 });
    await page.locator('button.accordion-button').filter({ hasText: 'What is Lorem Ipsum?' }).click();
    await expect(page.locator('button.accordion-button').filter({ hasText: 'What is Lorem Ipsum?' })).toHaveClass(/collapsed/, { timeout: 5000 });
    await page.locator('button.accordion-button').filter({ hasText: 'Why do we use it?' }).click();
    await expect(page.locator('button.accordion-button').filter({ hasText: 'Why do we use it?' })).toHaveClass(/collapsed/, { timeout: 5000 });
  });
});
